fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target_width = width as usize;

    if orig_len >= target_width {
        // If original length is greater or equal to target, return original unchanged.
        orig
    } else {
        // Need to pad on the left with fillchar so that total length == target_width.
        let pad_len = target_width - orig_len;
        // Create a vector with pad_len fillchars.
        let mut result = Vec::with_capacity(target_width);
        for _ in 0..pad_len {
            result.push(fillchar);
        }
        // Append the original sequence as suffix.
        result.extend(orig.into_iter());
        result
    }
}